 "content": "def transform(grid):
    """Restore cells hidden by 3s using the left-right mirrored pattern."""
    out = [row[:] for row in grid]
    width = len(grid[0])
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 3:
                mirror = width - 1 - c
                if grid[r][mirror] == 3:
                    raise ValueError("cannot infer a hidden cell from a 3 mirror")
                out[r][c] = grid[r][mirror]
    return out
